{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1302",
      "rationale": "Foundational course in deep learning, covering the basics and terminology related to deep learning."
    },
    {
      "step": 2,
      "course_id": "EDX2052",
      "rationale": "Builds on the foundational course in deep learning, covering hands-on experience and practice using Python to solve real data science challenges."
    },
    {
      "step": 3,
      "course_id": "EDX1901",
      "rationale": "Builds on the hands-on experience and practice in data science, covering the basics of machine learning using Python."
    },
    {
      "step": 4,
      "course_id": "EDX342",
      "rationale": "Builds on the basics of machine learning, covering the application of deep neural networks and related machine learning methods."
    },
    {
      "step": 5,
      "course_id": "EDX3425",
      "rationale": "Builds on the application of deep neural networks, covering the ability to apply data science and analysis techniques to inform decision-making."
    },
    {
      "step": 6,
      "course_id": "EDX1856",
      "rationale": "Builds on the ability to apply data science and analysis techniques, covering the fundamentals of machine learning and AI."
    },
    {
      "step": 7,
      "course_id": "EDX342",
      "rationale": "Builds on the fundamentals of machine learning and AI, covering the application of deep learning and related machine learning methods."
    },
    {
      "step": 8,
      "course_id": "EDX3437",
      "rationale": "Builds on the application of deep learning, covering the delivery of business value through AI in finance."
    }
  ]
}

