learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX3047",
      "rationale": "Foundational course in finance and accounting for a career change into banking."
    },
    {
      "step": 2,
      "course_id": "EDX469",
      "rationale": "Builds on existing knowledge of financial accounting and provides a comprehensive understanding of financial statements."
    },
    {
      "step": 3,
      "course_id": "EDX3298",
      "rationale": "Develops skills in financial analysis and provides a toolkit for making more strategic managerial and business decisions."
    },
    {
      "step": 4,
      "course_id": "EDX3046",
      "rationale": "Introduces fundamental concepts of financial markets and market participants, and evaluates the economic and industry environment in which companies operate."
    },
    {
      "step": 5,
      "course_id": "EDX3329",
      "rationale": "Provides the confidence to intelligently manage an investment portfolio alongside a financial advisor and develops skills in investment philosophy and constraints."
    },
    {
      "step": 6,
      "course_id": "EDX3009",
      "rationale": "Develops skills in financial modeling and provides an understanding of the fundamental principles of financial markets and market participants."
    },
    {
      "step": 7,
      "course_id": "EDX70",
      "rationale": "Provides an understanding of the relationship between risk and capital, and the role of Basel in bank risk management."
    },
    {
      "step": 8,
      "course_id": "EDX846",
      "rationale": "Develops skills in risk management and credit principles, and provides an understanding of the principles of corporate and project finance."
    },
    {
      "step": 9,
      "course_id": "EDX1622",
      "rationale": "Provides an understanding of the interaction between investing and financing, and the capital structure decisions within the firm."
    },
    {
      "step": 10,
      "course_id": "EDX1535",
      "rationale": "Develops skills in fixed income portfolio management and provides an understanding of the review of fixed income concepts and passive fixed income portfolio management."
    },
    {
      "step": 11,
      "course_id": "EDX91",
      "rationale": "Provides an understanding of the scope of personal financial planning and the impact of financial planning on personal goals."
    },
    {
      "step": 12,
      "course_id": "EDX3129",
      "rationale": "Develops skills in financial literacy and provides an understanding of the fundamental knowledge, skills, and tools of finance."
    },
    {
      "step": 13,
      "course_id": "EDX3393",
      "rationale": "Provides an understanding of the competency to assess a company's financial risks and evaluate systems of internal control."
    },
    {
      "step": 14,
      "course_id": "EDX1933",
      "rationale": "Develops skills in portfolio management and provides an understanding of the mutual fund overview, hedge fund overview, and private equity overview."
    },
    {
      "step": 15,
      "course_id": "EDX3307",
      "rationale": "Provides an understanding of the fintech industry and the new business opportunities it presents."
    },
    {
      "step": 16,
      "course_id": "EDX1304",
      "rationale": "Develops skills in portfolio management and provides an understanding of the capital markets, statistical tools for portfolio management, and risk and return measurement."
    },
    {
      "step": 17,
      "course_id": "EDX180",
      "rationale": "Provides an understanding of the importance of managing personal cash and credit, and the tools for making informed financial decisions."
    },
    {
      "step": 18,
      "course_id": "EDX3239",
      "rationale": "Develops skills in sustainable finance and provides an understanding of the environmental and social sustainability challenges and disruptions facing financial systems."
    },
    {
