      "step": 2,
      "course_id": "EDX1415",
      "rationale": "Builds on the foundational knowledge of nutrition science, focusing on identifying modifiable and non-modifiable risk factors for type 2 diabetes and cardiovascular disease."
    },
    {
      "step": 3,
      "course_id": "EDX3101",
      "rationale": "Develops practical skills in weight management, including measuring body composition, calories, and kilojoules, and identifying features of fad diets and healthy diets."
    },
    {
      "step": 4,
      "course_id": "EDX1335",
      "rationale": "Explores the impact of industrialized food production on individual and environmental health, and introduces the concept of whole food plant-based nutrition."
    },
    {
      "step": 5,
      "course_id": "EDX2620",
      "rationale": "Applies evidence-based practice in clinical nutrition, covering the treatment of obesity, diabetes, malnutrition, and gastrointestinal diseases."
    },
    {
      "step": 6,
      "course_id": "EDX2201",
      "rationale": "Develops essential competencies for nurse preceptors, including designing effective clinical teaching and learning experiences, and facilitating students' critical thinking and clinical decision-making."
